-- CheckObra 2.2: ejecutar en Supabase SQL Editor con rol postgres.
-- No borra datos existentes. Estados importados desde colores de la hoja principal del Excel.
create table if not exists public.excel_status (
 trade_id uuid not null references public.trades(id) on delete cascade,
 unit_id text not null references public.units(id) on delete cascade,
 status text not null check (status in ('Ejecutado','En proceso','Con observaciones')),
 source_sheet text not null,
 source_cell text not null,
 source_value text,
 imported_at timestamptz not null default now(),
 primary key(trade_id,unit_id)
);
alter table public.excel_status enable row level security;
drop policy if exists excel_status_read on public.excel_status;
create policy excel_status_read on public.excel_status for select to authenticated using(public.my_role() is not null);
grant select on public.excel_status to authenticated;
-- Los cambios de ejecución posteriores se registran en progress, sin alterar el Excel de origen.

create table if not exists public.staff_directory (
 full_name text primary key, role text not null default 'supervisor', active boolean not null default true,
 profile_id uuid references public.profiles(id)
);
alter table public.staff_directory enable row level security;
drop policy if exists staff_directory_read on public.staff_directory;
create policy staff_directory_read on public.staff_directory for select to authenticated using(public.my_role() is not null);
drop policy if exists staff_directory_write on public.staff_directory;
create policy staff_directory_write on public.staff_directory for all to authenticated using(public.is_manager()) with check(public.is_manager());
grant select,insert,update on public.staff_directory to authenticated;

